public class Foo {
    int fact(int n) {
        return n <= 1 ? 1 : n * this.fact(n - 1);
    }
}

public class Foo {
    static int fib(int n) {
        return n < 2 ? n : Foo.fib(n - 1) + Foo.fib(n - 2);
    }
}

public class Node {
    private Node next;

    int size() {
        if (next == null) {
            return 1;
        }
        return 1 + next.size();
    }
}

public enum Level {
    LOW;
    int depth(int n) {
        return n == 0 ? 0 : depth(n - 1);
    }
}

record Pair(int a, int b) {
    int sum(int n) {
        return n == 0 ? a : sum(n - 1);
    }
}

